const results = [];
for (const item of $input.all()) {
  const html = item.json.html || '';
  const plainText = html
    .replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
  results.push({ json: { ...item.json, plainText } });
}
return results;

const labelMap = {
  'Notification': 'REPLACE_WITH_NOTIFICATION_LABEL_ID',
  'Career': 'REPLACE_WITH_CAREER_LABEL_ID',
  'Financial': 'REPLACE_WITH_FINANCIAL_LABEL_ID',
  'Meeting/Calendar': 'REPLACE_WITH_MEETING_LABEL_ID',
  'Personal': 'REPLACE_WITH_PERSONAL_LABEL_ID',
  'Promotions': 'REPLACE_WITH_PROMOTIONS_LABEL_ID',
  'Action Required': 'REPLACE_WITH_ACTION_REQUIRED_LABEL_ID',
  'Work': 'REPLACE_WITH_WORK_LABEL_ID',
  'Other': 'REPLACE_WITH_OTHER_LABEL_ID'
};
const results = [];
for (const item of $input.all()) {
  try {
    const categories = JSON.parse(item.json.text);
    const labelIds = categories.map(cat => labelMap[cat] || null).filter(Boolean);
    results.push({ json: { category: categories, labelId: labelIds } });
  } catch (err) {
    results.push({ json: { category: [], labelId: [], error: 'Failed to parse categories' } });
  }
}
return results;
